<?php
namespace App\Services\Folios;
use App\Models\{Account,Folio,FolioItem,Payment,Reservation,Stay}; use App\Services\Accounting\AccountingService; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class FolioService {
 public function ensureForReservation(Reservation $reservation, ?Stay $stay=null):Folio { return Folio::firstOrCreate(['reservation_id'=>$reservation->id],['property_id'=>$reservation->property_id,'guest_id'=>$reservation->guest_id,'stay_id'=>$stay?->id,'folio_number'=>config('hms.folio_prefix','FOL').'-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'status'=>'open']); }
 public function postRoomCharges(Reservation $reservation,Folio $folio,int $userId):void { foreach($reservation->rooms as $rr){ $n=max(1,$rr->check_in_at->copy()->startOfDay()->diffInDays($rr->check_out_at->copy()->startOfDay())); $item=FolioItem::firstOrCreate(['folio_id'=>$folio->id,'source_type'=>'reservation_room','source_id'=>$rr->id],['type'=>'charge','department'=>'rooms','description'=>'Room '.$rr->room?->room_number.' - '.$n.' night'.($n===1?'':'s'),'quantity'=>$n,'unit_price'=>$rr->nightly_rate,'total'=>$n*(float)$rr->nightly_rate,'posted_by'=>$userId,'posted_at'=>now()]); if(!$item->journal_entry_id && Account::where('property_id',$folio->property_id)->where('code','4100')->exists()){ $je=app(AccountingService::class)->postRevenue($folio->property_id,$item->id,'room',(float)$item->total,0,$userId); $item->update(['journal_entry_id'=>$je->id]); } } $this->recalculate($folio); }
 public function addCharge(Folio $folio,array $data,int $userId):FolioItem { $item=$folio->items()->create(['type'=>'charge','department'=>$data['department']??'front_office','description'=>$data['description'],'quantity'=>$data['quantity'],'unit_price'=>$data['unit_price'],'tax_amount'=>$data['tax_amount']??0,'total'=>(($data['quantity']*$data['unit_price'])+($data['tax_amount']??0)),'posted_by'=>$userId,'posted_at'=>now()]); if(Account::where('property_id',$folio->property_id)->where('code','1100')->exists()){ $net=(float)$item->total-(float)$item->tax_amount; $je=app(AccountingService::class)->postRevenue($folio->property_id,$item->id,$item->department==='rooms'?'room':$item->department,$net,(float)$item->tax_amount,$userId); $item->update(['journal_entry_id'=>$je->id]); } $this->recalculate($folio); return $item; }
 public function recordPayment(Folio $folio,array $data,int $userId):Payment { return DB::transaction(function()use($folio,$data,$userId){$p=Payment::create(['property_id'=>$folio->property_id,'guest_id'=>$folio->guest_id,'reservation_id'=>$folio->reservation_id,'folio_id'=>$folio->id,'reference'=>'PAY-'.now()->format('YmdHis').'-'.strtoupper(Str::random(5)),'method'=>$data['method'],'gateway'=>$data['gateway']??null,'status'=>'successful','currency'=>config('hms.currency','UGX'),'amount'=>$data['amount'],'payer_phone'=>$data['payer_phone']??null,'gateway_reference'=>$data['gateway_reference']??null,'description'=>$data['description']??'Folio payment','paid_at'=>now(),'received_by'=>$userId]); if(Account::where('property_id',$folio->property_id)->where('code','1100')->exists()){ $je=app(AccountingService::class)->postPayment($folio->property_id,$p->id,$p->method,(float)$p->amount,$userId); $p->update(['journal_entry_id'=>$je->id]); } $this->recalculate($folio); if($folio->guest_id && config('hms.loyalty_spend_per_point',0)>0){$guest=\App\Models\Guest::find($folio->guest_id);$points=(int) floor(((float)$p->amount)/config('hms.loyalty_spend_per_point'));if($guest&&$points>0)app(\App\Services\CRM\LoyaltyService::class)->add($guest,$points,'Points earned from payment '.$p->reference,$p,$userId);} return $p;}); }
 public function recalculate(Folio $folio):Folio { $charges=(float)$folio->items()->where('type','charge')->sum('total'); $credits=(float)$folio->items()->where('type','credit')->sum('total'); $payments=(float)$folio->payments()->where('status','successful')->sum('amount'); $folio->update(['charges_total'=>$charges-$credits,'payments_total'=>$payments,'balance'=>($charges-$credits)-$payments]); return $folio->fresh(); }
}
